#include <bits/stdc++.h>
using namespace std;

int main(){
    int n;
    scanf("%d",&n);
    vector<int> p(n);
    for(int i=0;i<n;i++) scanf("%d",&p[i]);

    vector<pair<int,int>> ops;

    auto apply_op = [&](int x, int y){
        vector<int> np;
        for(int i=n-y;i<n;i++) np.push_back(p[i]);
        for(int i=x;i<n-y;i++) np.push_back(p[i]);
        for(int i=0;i<x;i++) np.push_back(p[i]);
        p=np;
        ops.push_back({x,y});
    };

    for(int target=0; target<n; target++){
        int pos=-1;
        for(int i=0;i<n;i++) if(p[i]==target+1){pos=i;break;}
        if(pos==target) continue;

        // Step 1: move element to position n-1
        // Element at pos. We want it at n-1.
        // p[0] goes to n-1 after any op. So first move element to position 0.
        // Element at pos -> position 0: use suffix starting at pos. y = n-pos, x needs x>0, x+n-pos<n => x<pos. So x=1 if pos>=2
        // If pos==0: already at 0.
        // If pos==1: x<1 impossible. Use different approach.

        if(pos != n-1){
            if(pos >= 2){
                // move to front: y=n-pos, x=1, need 1+n-pos<n => pos>1. Yes.
                apply_op(1, n-pos);
                pos=0;
            } else if(pos==1){
                // x=1,y=1 if n>2: moves p[1] to front? No. p[n-1]->0, p[1..n-2] stay, p[0]->n-1
                // Move pos=1: use x=1,y=n-2 if n>3: element at 1 goes to position y=n-2 (first of middle)
                // Actually let me just bring it to 0 by: x=1,y=1 => p=[p[n-1],p[1..n-2],p[0]], elem still at 1
                // Use x=2,y=n-3 if n>4... let me think. 
                // y=n-1,x=1: x+y=n not <n. 
                // Bring to 0: swap by x=1,y=1 first, then find again
                if(n>2){apply_op(1,1);}
                for(int i=0;i<n;i++) if(p[i]==target+1){pos=i;break;}
                if(pos>=2){apply_op(1,n-pos);pos=0;}
                // if pos==0 fine
            }
            // Now element is at position 0 (or still not n-1 if edge case)
            for(int i=0;i<n;i++) if(p[i]==target+1){pos=i;break;}
            if(pos==0 && n>2){
                // move 0->n-1: any op sends p[0] to n-1
                apply_op(1,1);
                pos=n-1;
            }
            for(int i=0;i<n;i++) if(p[i]==target+1){pos=i;break;}
        }

        if(pos==target) continue;
        if(pos!=n-1) continue; // shouldn't happen

        // Step 2: place at target. y=target+1 puts p[n-1] at position target.
        // Need x>0, x+target+1<n => x<n-target-1. Need n-target-1>1 => target<n-2.
        if(target<n-2){
            apply_op(1, target+1);
        }
    }

    printf("%d\n",(int)ops.size());
    for(auto&[x,y]:ops) printf("%d %d\n",x,y);
}
